=== PUBLIC BOUNDARY REPRODUCTIONS ===
CASE checksum-valid ID with impossible date must not match
REQUEST {"body": {"records": [{"x": "110105199902300023"}]}, "method": "POST", "path": "/v1/classify"}
ACTUAL {"response": {"results": [{"fields": [{"categories": ["direct_identifier"], "path": "/x", "sources": ["value"]}], "index": 0}]}, "status": 200}
CASE explicit schema null must be invalid_schema
REQUEST {"body": {"records": [{}], "schema": null}, "method": "POST", "path": "/v1/classify"}
ACTUAL {"response": {"error": {"code": "invalid_schema", "message": "schema must be a JSON object"}}, "status": 422}
CASE invalid category must not be echoed
REQUEST {"body": {"records": [{"x": "private-record-value"}], "schema": {"/x": "PRIVATE_CATEGORY_VALUE_92841"}}, "method": "POST", "path": "/v1/classify"}
ACTUAL {"response": {"error": {"code": "invalid_schema", "message": "unsupported category for '/x': 'PRIVATE_CATEGORY_VALUE_92841'"}}, "status": 422}
CASE schema path must remain /group
REQUEST {"body": {"records": [{"group": {"left": "plain", "right": "plain"}}], "schema": {"/group": "clinical"}}, "method": "POST", "path": "/v1/classify"}
ACTUAL {"response": {"results": [{"fields": [{"categories": ["clinical"], "path": "/group", "sources": ["schema"]}], "index": 0}]}, "status": 200}
CASE OPTIONS must be method_not_allowed
REQUEST {"body": null, "method": "OPTIONS", "path": "/v1/classify"}
ACTUAL {"response": {"error": {"code": "method_not_allowed", "message": "OPTIONS is not allowed for /v1/classify"}}, "status": 405}
